/bin/bash -lc "cat >> public/atlas.css <<'EOF'
/* The mobile title owns its line; the crystal never squeezes words. */
h1{overflow-wrap:normal;word-break:normal;hyphens:none}
@media(max-width:480px){.intro{grid-template-columns:minmax(0,1fr);gap:4px}.intro img{width:72px;justify-self:end}.intro h1{font-size:clamp(30px,9vw,40px);max-width:none}.intro p{margin-bottom:0}}
EOF
cat >> public/overlay.css <<'EOF'
.compact-state{display:none}
/* A complete 160px browser-source composition, not a cropped tall overlay. */
.corner .relic-overlay{position:relative;width:160px;height:160px;padding:4px;filter:none}
.corner .archive{position:absolute;top:18px;left:34px;width:92px;height:92px}
.corner .simulator{position:absolute;top:3px;left:4px;width:152px;height:14px;margin:0;padding:1px 0;font-size:8px;line-height:10px;white-space:nowrap}
.corner h1,.corner #status,.corner #count,.corner #lineage,.corner #handoff{position:absolute;width:1px;height:1px;padding:0;margin:0;clip-path:inset(50%);overflow:hidden;white-space:nowrap}
.corner .charge-track{position:absolute;top:111px;left:20px;width:120px;height:2px;margin:0}
.corner .compact-state{display:flex;position:absolute;top:116px;left:4px;width:152px;flex-direction:column;font-size:9px;line-height:12px;text-align:center}
.corner .compact-state span{display:block;white-space:nowrap}
.corner .rune{width:10px;height:10px}
.corner .archive[data-phase=streak] .crystal{transform:translateX(calc((1 - var(--arrival))* -100%)) rotate(-25deg)}
EOF
python3 - <<'PY'
from pathlib import Path
p=Path('public/overlay-live.html');s=p.read_text().replace('</main>', '<div class=\"compact-state\" aria-hidden=\"true\"><span id=\"compact-status\">Connecting…</span><span id=\"compact-count\">No current state</span><span id=\"compact-handoff\"></span></div></main>');p.write_text(s)
p=Path('public/overlay.js');s=p.read_text().replace(\"if ("'!snapshot) { count.textContent = '"'No current state'; return; }\", \"if ("'!snapshot) { count.textContent = '"'No current state'; document.querySelector('#compact-count').textContent = 'No current state'; return; }\");s=s.replace('  state.textContent = messages[snapshot.status];', \"  state.textContent = messages[snapshot.status];\\n  document.querySelector('#compact-status').textContent = { ready: 'Relic connected', paused: 'Marks paused', waiting: 'Waiting for Keeper', unavailable: 'State unavailable' }[snapshot.status];\\n  document.querySelector('#compact-count').textContent = "'`Charge ${snapshot.approvedCount}/160 · Rings ${snapshot.lineageRings}`;");s=s.replace("    if (value !== '"'connected') state.textContent\", \"    if (value "'!== '"'connected') document.querySelector('#compact-status').textContent = value === 'stale' ? 'State stale' : 'Reconnecting…';\\n    if (value "'!== '"'connected') state.textContent\");s=s.replace('  requestAnimationFrame(frame);', \"  document.querySelector('#compact-handoff').textContent = hop && time < hop.endsAt\\n    ? hop.completed ? 'Two-chat claim complete' : "'`Local ${Math.max(0, Math.ceil((hop.endsAt - time) / 1000))}s · O${hop.offers}/${hop.threshold} A${hop.accepts}/${hop.threshold}` : '"'';\\n  requestAnimationFrame(frame);\");p.write_text(s)
PY"

